insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-17','nieuw','Offertes','Verkoopkansen: bewaar het werk dat later terugkomt',
   'Gaat een offerte niet door maar komt het werk over een tijd terug? Leg dan een verkoopkans vast: waar het over gaat, wie erachteraan gaat en wanneer. Bij Uitgesteld vraagt EVA er zelf om, bij Verloren en Vervallen biedt hij het aan. Alle kansen staan bij elkaar achter de knop Verkoopkansen op het tabblad Aanvragen, waar je ze kunt openen, aanpassen en afvinken.'),
  ('2026-09-17','verbeterd','Offertes','Duidelijker kolommen en direct naar Bewaking',
   'Op het offertebord heet Nabellen voortaan Actie en In behandeling voortaan Wachten: in één oogopslag zie je of wij aan zet zijn of de klant. Klik je vanaf Offertes een dossier aan, dan open je meteen het tabblad Bewaking. De knop Aanpassen heet nu Volgende actie, en de kans op opdracht kies je in stappen van 5%.'),
  ('2026-09-17','verbeterd','Offertes','Bij vervallen vragen we nu ook waarom',
   'Zet je een dossier op Vervallen, dan vraagt EVA voortaan naar de reden — met een eigen lijst, want vervallen werk is iets anders dan een offerte die je van een concurrent verliest. Dat maakt het overzicht van verliesredenen onder Management een stuk bruikbaarder.');
